#!/usr/bin/env python3
import os, json, math, random, statistics
import numpy as np

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    """Schwarzschild radius r_s = 2GM/c^2"""
    return 2 * G * M / c**2

def isco_radius(M, a):
    """Prograde ISCO radius for a Kerr black hole.
    If a is positive (spinning in the same direction as the rotation) the
    prograde ISCO is closer than the counter‑rotating ISCO.  The formula
    returns the radius in metres.
    """
    # Ensure a is in the physical range [-1, 1]
    a = max(min(a, 0.999), -0.999)
    Z1 = 1 + (1 - a**2)**(1/3) * ((1 + a)**(1/3) + (1 - a)**(1/3))
    Z2 = math.sqrt(3*a**2 + 3*a + 2)
    if a >= 0:
        r_isco = M * (3 + Z2 - math.sqrt((3 - Z1)**2 + 3*a**2))
    else:
        r_isco = M * (3 + Z1 - math.sqrt((3 + Z2)**2 + 3*a**2))
    return r_isco * G / c**2  # convert to metres

def hawking_temperature(M):
    """Hawking temperature T_H = ħ c^3 / (8π G k_B M)"""
    return hbar * c**3 / (8 * math.pi * G * k_B * M)

def planck_length():
    """Planck length l_P = sqrt(ħ G / c^3)"""
    return math.sqrt(hbar * G) / c**3

def random_event():
    """Generate a random astrophysical event.
    Returns a dictionary with keys:
        mass_Msun (float),
        type (str),
        description (str).
    """
    # 10% chance of each type
    if random.random() < 0.10:
        return {
            "mass_Msun": random.uniform(1, 100),
            "type": "neutron_star",
            "description": "A neutron star with the given mass (solar masses) has been detected in the GWTC catalog.",
        }
    elif random.random() < 0.10:
        return {
            "mass_Msun": random.uniform(1, 100),
            "type": "black_hole",
            "description": "A supermassive black hole with the specified mass (solar masses) has been identified in the Event Horizon Telescope target list.",
        }
    else:
        return {
            "mass_Msun": random.uniform(1, 100),
            "type": "stellar_matter",
            "description": "A star‑forming region containing the stated mass (solar masses) of ionised matter has been observed by the James Webb Space Telescope.",
        }

if __name__ == "__main__":
    event = random_event()
    print(json.dumps(event, indent=2))

