#!/usr/bin/env python3
import os, json, math, sys

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

# Helper to load a GWTC catalog via environment variable

def load_gwtc_catalog():
    path = os.getenv('GWTC_CATALOG_PATH')
    if path and os.path.isfile(path):
        try:
            with open(path, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Failed to load catalog: {e}\nSkipping catalog check.")
    # Small synthetic fallback – may be insufficient for real analyses
    return {
        "events": [
            {"mass_1_source": 30.0, "mass_2_source": 35.0, "final_mass_source": 62.0},
            {"mass_1_source": 15.0, "mass_2_source": 15.0, "final_mass_source": 27.0}
        ]
    }

def compute_bh_gap_stats(events):
    gaps = []
    total = len(events)
    if total == 0:
        return None
    for ev in events:
        m1 = ev.get("mass_1_source")
        m2 = ev.get("mass_2_source")
        mf = ev.get("final_mass_source")
        if None in (m1, m2, mf):
            continue
        # Ensure values are positive
        if any(x <= 0 for x in (m1, m2, mf)):
            continue
        gaps.append((m1 + m2 - mf))
    if not gaps:
        return None
    gaps = [g for g in gaps if g > 0]  # ignore negative or zero gaps
    if not gaps:
        return None
    min_gap = min(gaps)
    max_gap = max(gaps)
    mean_gap = sum(gaps) / len(gaps)
    median_gap = gaps[len(gaps)//2]
    std_gap = math.sqrt(sum((g - mean_gap) ** 2 for g in gaps) / len(gaps))
    return {
        "total_events": total,
        "valid_events": len(gaps),
        "min_gap": min_gap,
        "max_gap": max_gap,
        "mean_gap": mean_gap,
        "median_gap": median_gap,
        "std_gap": std_gap,
    }

def main():
    catalog = load_gwtc_catalog()
    results = compute_bh_gap_stats(catalog.get("events", []))
    if results is None:
        print("No valid events found.")
        sys.exit(0)
    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

