import numpy as np, json, os, sys, math, random


def random_point():
    """Return a random 3‑vector of length 1 (x,y,z)."""
    phi = random.uniform(0, 2*math.pi)
    cos_theta = random.uniform(-1, 1)
    sin_theta = math.sqrt(1 - cos_theta**2)
    return np.array([sin_theta*math.cos(phi), sin_theta*math.sin(phi), cos_theta])


def random_point_cloud(N=2000):
    """Generate N random 3‑vectors of length 1."""
    return np.stack([random_point() for _ in range(N)], axis=0)


def main():
    points = random_point_cloud()
    radii = np.linalg.norm(points, axis=1)
    print("Mean radius:", np.mean(radii))
    print("Radius range:", np.min(radii), np.max(radii))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import os, json, numpy as np

# Physical constants (SI)
G = 6.67430e-11            # gravitational constant
c = 2.99792458e8           # speed of light
M_sun = 1.98847e30         # solar mass

# Helper: safe conversion to float, handling None/invalid entries

def safe_float(x):
    if x is None:
        return np.nan
    try:
        return float(x)
    except Exception:
        return np.nan

# Load GWTC catalog – expects environment variable GWTC_CATALOG_PATH
catalog_path = os.getenv('GWTC_CATALOG_PATH')
if not catalog_path:
    raise RuntimeError('Environment variable GWTC_CATALOG_PATH not set')

# Load catalog as JSON, discard any rows with missing required fields
with open(catalog_path, 'r') as f:
    data = json.load(f)

events = []
for ev in data.get('events', []):
    m1 = safe_float(ev.get('mass_1_source'))
    m2 = safe_float(ev.get('mass_2_source'))
    mf = safe_float(ev.get('final_mass_source'))
    if np.isnan((m1, m2, mf)).any():
        continue
    events.append((m1, m2, mf))

if not events:
    raise RuntimeError('No valid events found in the catalog')

# Compute radiated mass fraction for each event
radiated_fractions = []
for m1, m2, mf in events:
    total_initial = m1 + m2
    radiated = (m1 + m2) - mf
    fraction = radiated / total_initial
    radiated_fractions.append(fraction)

fractions_arr = np.array(radiated_fractions)
max_fraction = fractions_arr.max()
mean_fraction = fractions_arr.mean()

max_info = {
    'max_fraction': max_fraction,
}
for i, (m1, m2, mf) in enumerate(events):
    total_initial = m1 + m2
    radiated = (m1 + m2) - mf
    fraction = radiated / total_initial
    if np.isclose(fraction, max_fraction, atol=1e-12):
        max_info['event'] = f"event_{i}"
        break
else:
    max_info['event'] = None

print(f"Maximum radiated mass fraction: {max_info['max_fraction']:.4f}")
print(f"Mean radiated mass fraction:    {mean_fraction:.4f}")
if max_info.get('event'):
    print(f"Occurs in {max_info['event']}")
else:
    print("No events found with valid mass data.")

